<div class="modal fade" id="confirmModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered modal-sm"><div class="modal-content"><div class="modal-body text-center p-4"><i class="bi bi-exclamation-circle text-danger fs-1"></i><h6 class="mt-2" id="confirmModalLabel">Hapus data?</h6><p class="text-muted small" id="confirmModalMessage"></p></div><div class="modal-footer justify-content-center border-0"><button class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-danger" id="confirmModalYes">Ya, hapus</button></div></div></div></div>
<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script><script>
window.confirmDelete=function(message){const el=document.getElementById('confirmModal'),modal=bootstrap.Modal.getOrCreateInstance(el);document.getElementById('confirmModalMessage').textContent=message;return new Promise(resolve=>{let ok=false;document.getElementById('confirmModalYes').onclick=()=>{ok=true;modal.hide()};el.addEventListener('hidden.bs.modal',()=>resolve(ok),{once:true});modal.show()})};
document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('form[data-confirm]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();confirmDelete(f.dataset.confirm).then(ok=>{if(ok)f.submit()})}));document.querySelectorAll('[data-toggle-password]').forEach(b=>b.addEventListener('click',()=>{let i=document.getElementById(b.dataset.togglePassword);i.type=i.type==='password'?'text':'password';b.querySelector('i').className=i.type==='password'?'bi bi-eye':'bi bi-eye-slash'}));document.querySelectorAll('.alert-autohide').forEach(a=>setTimeout(()=>bootstrap.Alert.getOrCreateInstance(a).close(),4000))});
</script>@stack('scripts')
